// Claude returns query parameters (JSON). They are validated and clamped here, then a parameterised BigQuery query is built.
// The LLM never writes SQL: the SQL is fixed and values are passed as query parameters.
// The 0–100 score and the location score come from the view listings_scored (single source of truth, also used for new-listing messages).
const text = $('QueryInput').item.json.text;
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || '');
let p = {};
try { p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { p = {}; }

const tip = ['upit', 'oglas', 'ostalo'].includes(p.tip) ? p.tip : 'ostalo';
if (tip !== 'upit') {
  const help = 'Pošalji mi tekst FB oglasa da ga dodam u bazu, ili pitaj, npr.:\n• Daj mi 5 najboljih ponuda\n• Najjeftiniji dvosobni na Vračaru do 450 €\n• Najnoviji oglasi gde su dozvoljeni ljubimci';
  return { json: { tip, original: text, text: tip === 'ostalo' ? help : '' } };
}

const num = (v, def, min, max) => {
  const n = Number(v);
  return v === null || v === undefined || v === '' || !Number.isFinite(n) ? def : Math.min(max, Math.max(min, n));
};
const norm = s => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').trim();

const broj = Math.round(num(p.broj, 5, 1, 10));
const maxCena = Math.round(num(p.max_cena, 100000, 50, 100000));
const minM2 = num(p.min_m2, 0, 0, 500);
const minSobe = num(p.min_sobe, 0, 0, 10);
const dana = Math.round(num(p.dana, 14, 1, 60));
const opstine = (Array.isArray(p.opstine) ? p.opstine : []).map(norm).filter(Boolean).slice(0, 10);
const ljubimci = p.kucni_ljubimci === true;
const namesten = p.namesten === true;
const samoFilter = p.samo_filter !== false;
const sortiraj = ['vrednost', 'cena', 'najnovije', 'm2'].includes(p.sortiraj) ? p.sortiraj : 'vrednost';
const limit = Math.max(broj * 4, 20);

const sql = [
  "SELECT id, izvor, url, naslov, cena, m2, sobe, opstina, naselje, namesten, depozit_eur, kucni_ljubimci, bez_provizije, provizija, rezije_eur, oglasivac, grejanje,",
  "  kvalitet, kvalitet_opis, lok, cena_po_m2, ocena,",
  "  FORMAT_TIMESTAMP('%d.%m.', COALESCE(objavljeno, upisano), 'Europe/Belgrade') AS datum",
  "FROM `stan-hunter.stan_hunter.listings_scored`",
  "WHERE upisano >= TIMESTAMP_SUB(CURRENT_TIMESTAMP(), INTERVAL @dana DAY)",
  "  AND (NOT @samo_filter OR prosao_filter)",
  "  AND (cena IS NULL OR cena <= @max_cena)",
  "  AND (m2 IS NULL OR m2 >= @min_m2)",
  "  AND (sobe IS NULL OR sobe >= @min_sobe)",
  "  AND (NOT @filter_opstine OR EXISTS (SELECT 1 FROM UNNEST(@opstine) AS o WHERE STRPOS(TRANSLATE(LOWER(CONCAT(IFNULL(opstina, ''), ' ', IFNULL(naselje, ''))), 'čćšđž', 'ccsdz'), o) > 0))",
  "  AND (NOT @ljubimci OR kucni_ljubimci = 'da')",
  "  AND (NOT @namesten OR namesten = 'da')",
  "  AND NOT IFNULL(sumnjiv_oglas, FALSE)",
  "ORDER BY CASE @sortiraj WHEN 'cena' THEN CAST(cena AS FLOAT64) WHEN 'najnovije' THEN -UNIX_SECONDS(COALESCE(objavljeno, upisano)) WHEN 'm2' THEN -m2 ELSE -ocena END ASC NULLS LAST",
  "LIMIT " + limit
].join('\n');

const P = (name, type, value) => ({ name, parameterType: { type }, parameterValue: { value: String(value) } });
const queryParameters = [
  P('dana', 'INT64', dana),
  P('samo_filter', 'BOOL', samoFilter),
  P('max_cena', 'INT64', maxCena),
  P('min_m2', 'FLOAT64', minM2),
  P('min_sobe', 'FLOAT64', minSobe),
  P('filter_opstine', 'BOOL', opstine.length > 0),
  { name: 'opstine', parameterType: { type: 'ARRAY', arrayType: { type: 'STRING' } }, parameterValue: { arrayValues: (opstine.length ? opstine : ['-']).map(o => ({ value: o })) } },
  P('ljubimci', 'BOOL', ljubimci),
  P('namesten', 'BOOL', namesten),
  P('sortiraj', 'STRING', sortiraj)
];

const opis = [
  `poslednjih ${dana} dana`,
  samoFilter ? 'prolaze tvoj filter' : 'svi oglasi',
  maxCena < 100000 ? `do ${maxCena} €` : null,
  minM2 > 0 ? `od ${minM2} m²` : null,
  minSobe > 0 ? `sobe ≥ ${minSobe}` : null,
  opstine.length ? opstine.join(', ') : null,
  ljubimci ? 'ljubimci dozvoljeni' : null,
  namesten ? 'namešten' : null,
  sortiraj === 'vrednost' ? 'redosled: ocena (lokacija 30%, slike 30%, cena 15%, €/m² 10%, veličina 10%, namešten 5%)' : `redosled: ${sortiraj}`
].filter(Boolean).join(' · ');

return { json: { tip, text, broj, sortiraj, opis, request: { query: sql, useLegacySql: false, location: 'EU', parameterMode: 'NAMED', timeoutMs: 20000, queryParameters } } };

const r = $input.first().json;
const q = $('BuildQuery').first().json;
const fields = r.schema?.fields || [];
const NUM = ['INTEGER', 'INT64', 'FLOAT', 'FLOAT64', 'NUMERIC'];
const conv = (v, t) => v === null || v === undefined ? null : NUM.includes(t) ? Number(v) : (t === 'BOOLEAN' || t === 'BOOL') ? v === 'true' : v;
const rows = (r.rows || []).map(row => Object.fromEntries(row.f.map((c, i) => [fields[i].name, conv(c.v, fields[i].type)])));

// The same flat is often on several sites (same price, size, rooms and municipality) → keep the first one in database order.
// Municipality, not neighbourhood: sites name the neighbourhood of the same flat differently.
const norm = s => String(s ?? '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/đ/g, 'd').replace(/\bopstina\b/g, '').replace(/\s+/g, ' ').trim();
const seen = new Set();
const kandidati = rows.filter(k => {
  const place = norm(k.opstina) || norm(k.naselje);
  if (k.cena === null || k.m2 === null || !place) return true;
  const key = `${k.cena}|${k.m2}|${k.sobe ?? '-'}|${place}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});
return [{ json: { pitanje: q.text, broj: q.broj, opis: q.opis, kandidati, zavrseno: r.jobComplete !== false } }];

const data = $('RowsToListings').first().json;
const q = $('BuildQuery').first().json;
const byId = Object.fromEntries(data.kandidati.map(k => [k.id, k]));
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || '');
let izbor = [];
try {
  const p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  izbor = Array.isArray(p.izbor) ? p.izbor : [];
} catch (e) { izbor = []; }
const seen = new Set();
izbor = izbor.filter(x => x && byId[x.id] && !seen.has(x.id) && seen.add(x.id));
const claudeOk = izbor.length > 0;
if (q.sortiraj === 'vrednost') {
  // Order comes from the database formula (score 0–100); Claude only writes the reason.
  const razlozi = Object.fromEntries(izbor.map(x => [x.id, x.razlog]));
  izbor = data.kandidati.slice(0, data.broj).map(k => ({ id: k.id, razlog: razlozi[k.id] || '' }));
} else {
  izbor = izbor.slice(0, data.broj);
  if (!claudeOk) izbor = data.kandidati.slice(0, data.broj).map(k => ({ id: k.id, razlog: '' }));
}

// The model sometimes mixes a Cyrillic letter into Latin text → transliterate.
const CYR = { 'а':'a','б':'b','в':'v','г':'g','д':'d','ђ':'đ','е':'e','ж':'ž','з':'z','и':'i','ј':'j','к':'k','л':'l','љ':'lj','м':'m','н':'n','њ':'nj','о':'o','п':'p','р':'r','с':'s','т':'t','ћ':'ć','у':'u','ф':'f','х':'h','ц':'c','ч':'č','џ':'dž','ш':'š' };
const lat = s => String(s).replace(/[Ѐ-ӿ]/g, ch => {
  const low = ch.toLowerCase();
  const t = CYR[low] ?? '';
  return ch === low ? t : t.charAt(0).toUpperCase() + t.slice(1);
});
// If the model still writes EUR/evra → €.
const euro = s => String(s).replace(/\s*\b(EUR|eur|evra|evro)\b/g, ' €').replace(/\s+€/g, ' €');

// Telegram HTML: everything from the database and from Claude is escaped. Numbers are always printed from the database.
// The rank goes next to the address and the price on the next line, so "1. 400 €" doesn't read as 1.400 €.
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const v = (n, suf = '') => (n === null || n === undefined || n === '') ? '?' : `${n}${suf}`;
const lines = izbor.map((x, i) => {
  const k = byId[x.id];
  const mesto = esc([k.naselje, k.opstina].filter(Boolean).join(', ') || k.naslov || '?');
  const cena = `💶 <b>${v(k.cena, ' €')}</b> · ${v(k.m2, ' m²')} · ${v(k.sobe)} sobe` + (k.cena_po_m2 ? ` · ${k.cena_po_m2} €/m²` : '');
  const info = [
    k.ocena !== null && k.ocena !== undefined ? `⭐ ${k.ocena}/100 (lokacija ${k.lok}/5)` : null,
    k.kvalitet !== null && k.kvalitet !== undefined ? `📸 ${k.kvalitet}/5` : null,
    k.namesten && k.namesten !== 'nepoznato' ? `namešten: ${esc(k.namesten)}` : null,
    k.datum ? `od ${esc(k.datum)}` : null,
    esc(k.izvor)
  ].filter(Boolean).join(' · ');
  const link = k.url ? `<a href="${esc(k.url)}">Otvori oglas</a>` : '(FB oglas, bez linka)';
  const razlog = x.razlog ? `\n👉 ${esc(euro(lat(x.razlog)).slice(0, 160))}` : '';
  return `<b>${i + 1}) ${mesto}</b>\n${cena}\n${info}${razlog}\n${link}`;
});
const header = `🏆 <b>Top ${izbor.length} iz baze</b>\n<i>${esc(data.opis)}</i>`;
const note = claudeOk ? '' : '\n\n<i>Claude nije odgovorio, pa nema razloga uz oglase.</i>';

// Buttons "❌ N": the listing with that number no longer exists → Telegram intake deletes it from the table.
// callback_data is limited to 64 bytes.
const buttons = izbor
  .map((x, i) => ({ text: `❌ ${i + 1}`, callback_data: `del:${x.id}` }))
  .filter(b => /^del:[A-Za-z0-9_-]{1,60}$/.test(b.callback_data));
const footer = buttons.length ? '\n\n<i>❌ N = oglas pod tim brojem više ne postoji (briše se iz baze)</i>' : '';
const reply_markup = buttons.length ? { inline_keyboard: [buttons] } : null;
return [{ json: { tip: 'upit', text: `${header}\n\n${lines.join('\n\n')}${note}${footer}`, reply_markup } }];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $input.first().json;
const text = d.zavrseno
  ? `Nema oglasa u bazi za te uslove (${esc(d.opis)}). Probaj šire: veći budžet, više dana ili bez opštine.`
  : 'BigQuery upit je trajao predugo. Probaj ponovo za minut.';
return [{ json: { tip: 'upit', text } }];
